svg.script:

(function() {
  // Data Dictionary for the 7 nominal structures
  var a12p21hData = {
    pubis: {
      title: "1. MONTE PÚBICO (MONTE DE VÊNUS)",
      text: ["• Proeminência adiposa anterior sobre a sínfise púbica.", "• Coberta por pele e pelos pubianos na puberdade.", "• Protege os ossos pélvicos durante o coito."],
      color: "var(--a12p21h-text-main, #fce8f3)",
      mode: "ext"
    },
    clitoris: {
      title: "2. CLITÓRIS (GLANDE E PREPÚCIO)",
      text: ["• Principal corpo erétil e de sensibilidade feminina.", "• Formado pela glande, capuz (prepúcio) e frênulo.", "• Localizado na junção anterior dos pequenos lábios."],
      color: "var(--a12p21h-brand-pink, #e64980)",
      mode: "vest"
    },
    urethra: {
      title: "3. ÓSTIO URETRAL EXTERNO",
      text: ["• Abertura da uretra no vestíbulo vulvar.", "• Situado entre o clitóris e o intróito vaginal.", "• Margens fendas mucosas revestidas por glândulas."],
      color: "var(--a12p21h-text-main, #fce8f3)",
      mode: "vest"
    },
    minora: {
      title: "4. PEQUENOS LÁBIOS (LABIA MINORA)",
      text: ["• Dobras mucocutâneas internas delgadas e vascularizadas.", "• Delimitam o vestíbulo vulvar.", "• Anteriormente fundem-se para formar o prepúcio clitoridiano."],
      color: "var(--a12p21h-brand-pink, #e64980)",
      mode: "ext"
    },
    majora: {
      title: "5. GRANDES LÁBIOS (LABIA MAJORA)",
      text: ["• Dobras cutâneas espessas laterais contendo tecido adiposo.", "• Delimitam a fenda vulvar externamente.", "• Unem-se na comissura posterior e monte púbico."],
      color: "var(--a12p21h-text-main, #fce8f3)",
      mode: "ext"
    },
    introitus: {
      title: "6. INTRÓITO VAGINAL",
      text: ["• Abertura inferior da vagina no vestíbulo.", "• Posterior ao óstio uretral e anterior à fossa navicular.", "• Sede da inserção e limites das carúnculas himenais."],
      color: "var(--a12p21h-brand-pink, #e64980)",
      mode: "vest"
    },
    hymen: {
      title: "7. CARÚNCULA HIMENAL (MARCO ZERO POP-Q)",
      text: [
        "• Remanescentes mucosos do hímen cicatrizado.",
        "• MARCO ZERO (0 cm): Referência oficial do sistema POP-Q.",
        "✔ 0 cm: Nível no plano das carúnculas himenais.",
        "▲ Valores Negativos (-cm): Ponto acima/proximal ao hímen.",
        "✖ Valores Positivos (+cm): Ponto prolapsado distal ao hímen."
      ],
      color: "var(--a12p21h-color-gold, #ffd43b)",
      mode: "popq"
    }
  };

  // Callout Mappings
  var calloutMap = {
    pubis: "a12p21h-callout-pubis",
    clitoris: "a12p21h-callout-clitoris",
    urethra: "a12p21h-callout-urethra",
    minora: "a12p21h-callout-minora",
    majora: "a12p21h-callout-majora",
    introitus: "a12p21h-callout-introitus",
    hymen: "a12p21h-callout-hymen"
  };

  // Current State
  var currentMode = "popq"; // Default active mode: POP-Q Marco Zero
  var activeId = "hymen";

  function updateUI() {
    // 1. Update Buttons
    var btns = {
      ext: document.getElementById("a12p21h-btn-ext"),
      vest: document.getElementById("a12p21h-btn-vest"),
      popq: document.getElementById("a12p21h-btn-popq"),
      all: document.getElementById("a12p21h-btn-all")
    };
    for (var k in btns) {
      if (btns[k]) {
        if (k === currentMode) {
          btns[k].classList.add("a12p21h-btn-active");
        } else {
          btns[k].classList.remove("a12p21h-btn-active");
        }
      }
    }

    // 2. Filter Callout Labels (Max 5 active rule enforcement!)
    for (var id in calloutMap) {
      var el = document.getElementById(calloutMap[id]);
      if (!el) continue;

      var visible = false;
      if (currentMode === "all") {
        visible = true;
      } else if (currentMode === "ext" && (id === "pubis" || id === "majora" || id === "minora")) {
        visible = true;
      } else if (currentMode === "vest" && (id === "clitoris" || id === "urethra" || id === "introitus")) {
        visible = true;
      } else if (currentMode === "popq" && (id === "hymen" || id === "introitus")) {
        visible = true;
      }

      if (visible) {
        el.classList.remove("a12p21h-hidden");
      } else {
        el.classList.add("a12p21h-hidden");
      }

      if (id === activeId) {
        el.classList.add("a12p21h-active");
      } else {
        el.classList.remove("a12p21h-active");
      }
    }

    // 3. Highlight Anatomy Shapes
    var parts = document.querySelectorAll(".a12p21h-anat-part");
    parts.forEach(function(part) {
      var pId = part.getAttribute("data-id");
      if (pId === activeId) {
        part.classList.add("a12p21h-active");
        part.classList.remove("a12p21h-dimmed");
      } else {
        part.classList.remove("a12p21h-active");
        if (activeId !== null) {
          part.classList.add("a12p21h-dimmed");
        } else {
          part.classList.remove("a12p21h-dimmed");
        }
      }
    });

    // 4. POP-Q Ruler Visualizer Toggle
    var popqVis = document.getElementById("a12p21h-popq-visualizer");
    if (popqVis) {
      if (currentMode === "popq" || activeId === "hymen") {
        popqVis.classList.remove("a12p21h-hidden");
      } else {
        popqVis.classList.add("a12p21h-hidden");
      }
    }

    // 5. Update Right Clinical Detail Box
    var titleEl = document.getElementById("a12p21h-detail-title");
    var contentEl = document.getElementById("a12p21h-detail-content");
    var data = a12p21hData[activeId] || a12p21hData["hymen"];

    if (titleEl) {
      titleEl.textContent = data.title;
      titleEl.setAttribute("fill", data.color);
    }

    if (contentEl) {
      var htmlText = "";
      data.text.forEach(function(line, idx) {
        var yPos = 16 + (idx * 20);
        var color = "var(--a12p21h-text-muted, #d4a5c3)";
        var weight = "500";
        if (line.indexOf("✔") >= 0) { color = "var(--a12p21h-color-normal, #20c997)"; weight = "700"; }
        if (line.indexOf("▲") >= 0) { color = "var(--a12p21h-color-warning, #ffc078)"; weight = "700"; }
        if (line.indexOf("✖") >= 0) { color = "var(--a12p21h-color-alert, #ff6b6b)"; weight = "700"; }
        if (line.indexOf("MARCO ZERO") >= 0) { color = "var(--a12p21h-color-gold, #ffd43b)"; weight = "800"; }

        htmlText += '<text y="' + yPos + '" fill="' + color + '" font-size="11" font-weight="' + weight + '">' + line + '</text>';
      });
      contentEl.innerHTML = htmlText;
    }
  }

  // Attach Event Listeners
  function initEvents() {
    // Anatomy clicks
    var parts = document.querySelectorAll(".a12p21h-anat-part");
    parts.forEach(function(part) {
      part.addEventListener("click", function(e) {
        e.stopPropagation();
        activeId = part.getAttribute("data-id");
        updateUI();
      });
    });

    // Mode button clicks
    var bExt = document.getElementById("a12p21h-btn-ext");
    var bVest = document.getElementById("a12p21h-btn-vest");
    var bPopq = document.getElementById("a12p21h-btn-popq");
    var bAll = document.getElementById("a12p21h-btn-all");

    if (bExt) bExt.addEventListener("click", function() { currentMode = "ext"; activeId = "pubis"; updateUI(); });
    if (bVest) bVest.addEventListener("click", function() { currentMode = "vest"; activeId = "clitoris"; updateUI(); });
    if (bPopq) bPopq.addEventListener("click", function() { currentMode = "popq"; activeId = "hymen"; updateUI(); });
    if (bAll) bAll.addEventListener("click", function() { currentMode = "all"; activeId = "hymen"; updateUI(); });

    // Initial UI Render
    updateUI();
  }

  // Initialize on Load
  if (document.readyState === "complete" || document.readyState === "interactive") {
    initEvents();
  } else {
    document.addEventListener("DOMContentLoaded", initEvents);
  }
})();
